  const len = seq.length;
  const fix = (i: number): number =>
    i < 0 ? Math.max(len + i, 0) : Math.min(i, len);
  const stepSize = st ?? 1;
  if (stepSize === 0) throw new ValueError("slice step cannot be zero");
